head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDBNS21000.xml";
// grid resize 시작부
frame.SetEvent("onwinstat", OnWinStat);
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.isCtrl = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    var gw = (a - parseInt(grd_List.getStyle("width")) - 30);
    grd_List.ReDraw = "false";
    grd_List.setGridWidth(parseInt(grd_List.getStyle("width")) + gw);
    grd_List.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    var pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "panel_Top");
    pnl_main_grp.style.setGridWidth(parseInt(pnl_main_grp.style.width.replace("px", "")) + gw); // 상단패널
    panel_Top.style.width = parseInt(panel_Top.style.width.replace("px", "")) + gw;
};


// grid resize 종료부


scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fn_RefreshForm = function(interval) {
    setInterval("fn_list_sync();", interval);
};


/*직전영업일 가져옴*/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_FRN_MGR_LIST";
    url += "&queryId=lds.stf.bnsfrn_mgr.select.list";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISUR_VAL=" + $c.stf.getObjectValue(txb_com_abbrv);
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_EDate);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_com_abbrv)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다. 
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_com_abbrv, arrPar[0].ISUR_CD);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(img_com_srch) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_com_srch);
};


/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        BND_LIST_PROCS_TP_CD: '2'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.img_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Excel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var xls_path = $c.session.getExcelDownPath() + "변동금리채금리변경일_" + today + ".xlsx";
    $c.data.downloadGridViewOffice(grd_List, "sheet1", xls_path, 8, 0);
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    //edt_EDate.text = cGetToday("yyyymmdd");		// 현재날짜
    edt_EDate.setValue($c.ut.cGetPlusDate2($c.ut.cGetToday("yyyymmdd"), 3));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 5));
    scwin.fn_list_sync();
    scwin.fn_RefreshForm(60000);
};
scwin.img_com_srch_onclick = function() {
    scwin.fn_ShowIsur(img_com_srch);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (row > 0) {
        scwin.fn_GetPar = fn_GetParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(grd_List);
    }
};
